#!/usr/bin/env bash
# Runs the pure-Kotlin sim tests WITHOUT Gradle/Android (DataParityTest needs kotlinx-serialization, so it is Gradle-only).
# Needs kotlinc on PATH (or KOTLINC=/path/to/kotlinc). The real JUnit tests still run in CI via Gradle.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
KOTLINC="${KOTLINC:-kotlinc}"
export JAVA_OPTS="${JAVA_OPTS:--Xmx4g}"  # kotlinc needs a bigger heap for the whole sim package
OUT="$(mktemp -d)"
JUNIT_STUB="$ROOT/tools/parity/junit-stub"
"$KOTLINC" "$JUNIT_STUB/Stub.kt" -d "$OUT/junit.jar"
"$KOTLINC" "$ROOT"/app/src/main/java/com/oersted/trainer/sim/*.kt \
  "$ROOT"/app/src/test/java/com/oersted/trainer/sim/SimMathTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/SimTypesTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/ElectricalParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/ServicesParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/AuxPowerParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/FuelFeedParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/BleedParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/PackParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/HydraulicsParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/GearParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/AutobrakeParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/StartBleedParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/CargoFireParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/HydraulicCautionParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/InterlocksParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/FlightControlParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/HydraulicUsersParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/ElectricalUsersParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/ComponentsParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/ReturnFieldsParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/LightsParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/AllReturnParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/StepParityTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/StepSimTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/FlightPhasesTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/PlanGuidanceTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/FlightNavigationTest.kt "$ROOT"/app/src/test/java/com/oersted/trainer/sim/